// Settings visual baselines (#284): every viewport × theme project (360/768/1280, light and dark)
// with the clock frozen: the profile (owner, and read-only for a clerk), the rename dialog open,
// and each section placeholder in the shell. Baselines live in e2e/__screenshots__ and are only
// ever generated by the e2e workflow's `update_snapshots` dispatch in the pinned Playwright image
// (see e2e/README.md); without one the test is skipped.
import { existsSync } from 'node:fs';

import type { Page, TestInfo } from '@playwright/test';

import type { AsUser } from '../../fixtures/auth.ts';
import { expect, test } from '../../fixtures/index.ts';
import { shellReady } from '../shell/helpers.ts';

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

async function open(page: Page, asUser: AsUser, path: string, role: 'owner' | 'clerk' = 'owner') {
  await asUser(role, { path });
  await expect(page.locator('main').getByRole('heading', { level: 1 })).toBeVisible();
  await shellReady(page);
}

interface Shot {
  name: string;
  setUp: (page: Page, asUser: AsUser) => Promise<void>;
}

const SHOTS: readonly Shot[] = [
  { name: 'settings-profile.png', setUp: (page, asUser) => open(page, asUser, 'settings/profile') },
  {
    name: 'settings-profile-clerk.png',
    setUp: (page, asUser) => open(page, asUser, 'settings/profile', 'clerk'),
  },
  {
    name: 'settings-profile-rename.png',
    setUp: async (page, asUser) => {
      await open(page, asUser, 'settings/profile');
      await page.getByRole('button', { name: 'Rename' }).click();
      await expect(page.getByRole('dialog', { name: 'Rename the web address' })).toBeVisible();
    },
  },
  ...(['roles', 'integrations', 'privacy', 'export', 'danger'] as const).map((section) => ({
    name: `settings-${section}.png`,
    setUp: (page: Page, asUser: AsUser) => open(page, asUser, `settings/${section}`),
  })),
];

test.describe('settings visual baselines', () => {
  for (const shot of SHOTS) {
    test(shot.name, async ({ page, asUser }, testInfo) => {
      skipWithoutBaseline(testInfo, shot.name);
      await shot.setUp(page, asUser);
      await expect(page).toHaveScreenshot(shot.name, { animations: 'disabled', caret: 'hide' });
    });
  }
});
